<?php
require __DIR__.'/app/bootstrap.php';
$userId=require_auth();$pdo=db();$tripId=(int)($_GET['id']??$_POST['trip_id']??0);$service=new ProactiveTravelService($pdo);$error='';
$trip=(new DreamService($pdo))->get($userId,$tripId,false);if(!$trip){http_response_code(404);exit('Trip not found.');}
if($_SERVER['REQUEST_METHOD']==='POST'){
    verify_csrf();try{$action=(string)($_POST['action']??'assess');if($action==='dismiss'){$service->dismissIssue($userId,$tripId,(int)($_POST['issue_id']??0));flash('success','That proactive issue was dismissed. A materially different future issue can still surface.');}elseif($action==='assess'){$service->assessTrip($userId,$tripId,true,'worker');flash('success','Vacation Brain reassessed the saved trip data. No external provider refresh was triggered.');}else throw new InvalidArgumentException('Unknown proactive action.');redirect('proactive-trip.php?id='.$tripId);}catch(Throwable $e){$error=$e->getMessage();}
}
$assessment=$service->ready()?$service->assessTrip($userId,$tripId,true,'worker'):['ready'=>false,'enabled'=>false,'issues'=>[],'risk_score'=>0,'risk_label'=>'Upgrade required','health'=>[],'preferences'=>$service->preferences($userId)];$issues=$assessment['issues']??[];$briefings=$service->recentBriefings($userId,$tripId,7);$success=flash('success');$title='Proactive Vacation Brain — '.(string)$trip['name'];$pageStyles=['assets/proactive-travel.css','assets/live-travel-data.css'];require __DIR__.'/partials/header.php';
?>
