<?php if(!$service->ready()):?><div class="alert warning"><strong>Migration 047 / app v1.39 is required.</strong> <?php if(is_admin()):?><a href="<?=e(app_url('upgrade.php'))?>">Run System Upgrade →</a><?php endif;?></div><?php endif;?><?php if($success):?><div class="alert success"><?=e($success)?></div><?php endif;?><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?>
<div class="vb-proactive-hero dashboard-card"><div><span class="eyebrow">Current trip risk</span><div class="vb-proactive-score-row"><strong class="vb-proactive-score"><?=(int)($assessment['risk_score']??0)?></strong><div><h2><?=e((string)($assessment['risk_label']??'Under control'))?></h2><p><?=count($issues)?> open signal<?=count($issues)===1?'':'s'?> · automatic research <?=!empty($assessment['preferences']['auto_research'])?'on':'off'?> · changes still require approval.</p></div></div></div><div class="vb-proactive-scale" aria-label="Risk score"><span style="width:<?=max(0,min(100,(int)($assessment['risk_score']??0)))?>%"></span></div></div>
